import importlib.util,json,sys,hashlib,math
from pathlib import Path
import numpy as np
root=Path('/home/sasaki/datasets/openloris/corridor1-1-m8-observation-geometry-v1')
repo=Path.cwd()
s=importlib.util.spec_from_file_location('root_geometry_audit',repo/'scripts/audit_ba_geometry_bins.py')
m=importlib.util.module_from_spec(s);sys.modules[s.name]=m;s.loader.exec_module(m)
reports={arm:json.loads((root/(arm+'.json')).read_text()) for arm in ('initial','legacy','adaptive','ceres','ceres-repeat')}
a=dict(reports['ceres']);b=dict(reports['ceres-repeat']);a.pop('runtime');b.pop('runtime');assert a==b
source=Path('/home/sasaki/datasets/openloris/corridor1-1-m8-dense256x2-1k-control-v1/rig-legacy-cap256/model')
model=m._PUBLISH.parse_model(source)
# Independent vectorized row traversal: min absolute dot then acos, no pair matrix.
centres={}
for im in model.images:
    R=np.array(m._AUDIT.rotation(im.q))
    centres[im.image_id]=np.linalg.solve(R,-np.array(im.t))
counts=np.zeros((4,4,2),dtype=np.int64)
for p in model.points:
    rays=np.array([np.array(p.xyz)-centres[i] for i,_ in p.track])
    rays/=np.linalg.norm(rays,axis=1)[:,None]
    smallest=1.
    for i in range(1,len(rays)):
        smallest=min(smallest,float(np.min(np.abs(rays[:i]@rays[i]))))
    angle=math.degrees(math.acos(max(0.,min(1.,smallest))))
    ki=int(np.searchsorted([4,9,17],len(rays),side='right'))
    ai=int(np.searchsorted([.1,1.,5.],angle,side='right'))
    counts[ki,ai]+=[1,len(rays)]
for report in reports.values():
    assert len(report['cells'])==16
    for index,cell in enumerate(report['cells']):
        assert [cell['points'],cell['observations']]==counts[index//4,index%4].tolist()
    assert report['runtime']['peak_rss_kib']<=524288
    for dirname,expected in [(source,report['initial_file_hashes'])]:
        for name,digest in expected.items(): assert hashlib.sha256((dirname/name).read_bytes()).hexdigest()==digest
expected_cost={'initial':126510.39875730938,'legacy':118070.5543689159,'adaptive':113550.2193390116,'ceres':113473.87998203756}
diff={}
summary={}
for arm in expected_cost:
    r=reports[arm];g=r['global'];diff[arm]=g['candidate_squared_cost']-expected_cost[arm]
    assert abs(diff[arm])<1e-6
    groups={}
    for name,pred in [('angle_below_0.1',lambda c:c['angle_bin_deg']=='angle_0_0.1_deg'),('angle_below_1',lambda c:c['angle_bin_deg'] in ('angle_0_0.1_deg','angle_0.1_1_deg')),('long_tracks',lambda c:c['k_stratum']=='k_17_plus')]:
        cells=[c for c in r['cells'] if pred(c)]
        groups[name]={k:math.fsum(c[k] for c in cells) for k in ['points','observations','cost_reduction','cost_increase','landmark_displacement_sum_m']}
        groups[name]['net_cost_reduction']=groups[name]['cost_reduction']-groups[name]['cost_increase']
    summary[arm]={'groups':groups,'global':g,'runtime':r['runtime']}
print(json.dumps({'independent_population_audit':'PASS','method':'min absolute dot per vectorized row; camera centre via linear solve; O(maxtrack) scratch; all4716points','counts':counts.tolist(),'repeat_exact_excluding_runtime':True,'cost_absolute_tolerance':1e-6,'cost_differences_to_prior_evidence':diff,'summary':summary},sort_keys=True))
